{
  "$schema": "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json",
  "name": "egm",
  "version": "0.1.0",
  "description": "Draft specs, review designs, and check implementation drift.",
  "author": {
    "name": "Google"
  },
  "homepage": "https://egm.dev",
  "repository": "https://github.com/google/elephant-goldfish-model",
  "license": "Apache-2.0",
  "extensions": {
    "com.openai": {
      "requires_local_executor": true,
      "interface": {
        "displayName": "Elephant-Goldfish Model",
        "shortDescription": "Draft and stress-test specs",
        "longDescription": "Draft specs, review designs with fresh-context reviewers, resolve findings, and check implementation drift. Uses your host's models and permissions. Reviews require isolated subagents; cloud support remains partial. Not an officially supported Google product.",
        "developerName": "Google",
        "brandColor": "#1B6EF3",
        "category": "Developer Tools",
        "capabilities": ["Draft specifications", "Review designs", "Check implementation drift"],
        "websiteURL": "https://egm.dev",
        "supportURL": "https://github.com/google/elephant-goldfish-model/issues",
        "privacyPolicyURL": "https://github.com/google/elephant-goldfish-model/blob/main/docs/privacy.md",
        "termsOfServiceURL": "https://github.com/google/elephant-goldfish-model/blob/main/LICENSE",
        "composerIcon": "./assets/icon.svg",
        "logo": "./assets/icon.svg"
      }
    }
  }
}
